import type { SQLiteDatabase } from 'expo-sqlite';
import { newId } from '../lib/ids';
import { nowIso } from '../lib/date';

export type Inspection = {
  id: string; title: string; status: string; site: string | null; updated_at: string;
};

export function listInspections(db: SQLiteDatabase) {
  return db.getAllAsync<Inspection>(
    'SELECT * FROM inspections ORDER BY updated_at DESC'
  );
}

export async function seedInspections(db: SQLiteDatabase) {
  const row = await db.getFirstAsync<{ n: number }>('SELECT COUNT(*) AS n FROM inspections');
  if (row && row.n > 0) return;
  for (const [title, site] of [['Fire exits check', 'Warehouse B'], ['Crane service', 'Dock 4'], ['Scaffold audit', 'Site 12']]) {
    await db.runAsync(
      'INSERT INTO inspections (id, title, status, site, updated_at) VALUES (?, ?, ?, ?, ?)',
      newId(), title, 'open', site, nowIso()
    );
  }
}
```

