import { useEffect, useState } from 'react';
import { FlatList, Text, View } from 'react-native';
import { useSQLiteContext } from 'expo-sqlite';
import { listInspections, seedInspections, type Inspection } from '../db/inspections-repo';
import { formatDate } from '../lib/date';
import { useUiStore } from '../state/ui-store';

export function InspectionsListScreen() {
  const db = useSQLiteContext();
  const filter = useUiStore((s) => s.statusFilter);
  const [rows, setRows] = useState<Inspection[]>([]);

  useEffect(() => {
    seedInspections(db).then(() => listInspections(db)).then(setRows);
  }, [db]);

  const visible = filter === 'all' ? rows : rows.filter((r) => r.status === filter);

  return (
    <FlatList
      data={visible}
      keyExtractor={(r) => r.id}
      renderItem={({ item }) => (
        <View style={{ padding: 16 }}>
          <Text>{item.title}</Text>
          <Text>{item.site} - {formatDate(item.updated_at)}</Text>
        </View>
      )}
    />
  );
}
```

