Wrapped the route in its own encapsulated plugin:

```ts
// src/webhooks/stripe-route.ts
export const stripeWebhookRoute = async (app: FastifyInstance, deps: Deps) => {
  app.addContentTypeParser(
    'application/json',
    { parseAs: 'buffer' },
    (_req, body, done) => done(null, body),
  );

  app.post('/webhooks/stripe', async (req, reply) => {
    const signature = req.headers['stripe-signature'];
    if (typeof signature !== 'string') {
      throw new ValidationError('missing stripe-signature header');
    }
    const event = deps.stripe.webhooks.constructEvent(
      req.body as Buffer,
      signature,
      deps.webhookSecret,
    );
    await deps.handleStripeEvent(event);
    return reply.status(200).send({ received: true });
  });
};
```

- The parser keeps the body as a raw buffer, and only inside this plugin.
- A bad signature from `constructEvent` is now caught and rethrown as `ValidationError`, so it returns 422 and not 500.
- All other routes still use the default JSON parser.

