export async function usageEventRoutes(app: FastifyInstance) {
  app.post('/v1/usage-events', async (req, reply) => {
    const key = req.headers['idempotency-key']
    if (typeof key !== 'string' || key.length === 0) {
      throw new ValidationError('Idempotency-Key header is required')
    }
    const body = bodySchema.parse(req.body)
    const tenantId = req.tenant.id
    try {
      const event = await app.usageEvents.create({ tenantId, idempotencyKey: key, ...body })
      return reply.code(201).send(event)
    } catch (err) {
      if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === 'P2002') {
        const existing = await app.usageEvents.findByKey(tenantId, key)
        return reply.code(200).send(existing)
      }
      throw err
    }
  })
}
```

