```ts
// src/sync/hlc.ts
export type Hlc = { wall: number; counter: number; nodeId: string };

export const compareHlc = (a: Hlc, b: Hlc): number => {
  if (a.wall !== b.wall) return a.wall - b.wall;
  if (a.counter !== b.counter) return a.counter - b.counter;
  return a.nodeId < b.nodeId ? -1 : a.nodeId > b.nodeId ? 1 : 0;
};

export const tick = (state: Hlc, now: number): Hlc => {
  if (now > state.wall) return { ...state, wall: now, counter: 0 };
  return { ...state, counter: state.counter + 1 };
};

export const receive = (state: Hlc, remote: Hlc, now: number): Hlc => {
  const wall = Math.max(state.wall, remote.wall, now);
  if (wall === state.wall && wall === remote.wall) {
    return { ...state, wall, counter: Math.max(state.counter, remote.counter) + 1 };
  }
  if (wall === state.wall) return { ...state, wall, counter: state.counter + 1 };
  if (wall === remote.wall) return { ...state, wall, counter: remote.counter + 1 };
  return { ...state, wall, counter: 0 };
};
```

