// src/email/resend-webhook.ts
export async function resendWebhookRoute(app: FastifyInstance) {
  app.addContentTypeParser("application/json", { parseAs: "buffer" }, (_r, body, done) => done(null, body));

  app.post("/webhooks/resend", async (req, reply) => {
    const payload = req.body as Buffer;
    let event;
    try {
      event = resend.webhooks.verify({
        payload: payload.toString("utf8"),
        headers: {
          id: req.headers["svix-id"] as string,
          timestamp: req.headers["svix-timestamp"] as string,
          signature: req.headers["svix-signature"] as string,
        },
        webhookSecret: env.RESEND_WEBHOOK_SECRET,
      });
    } catch {
      return reply.status(400).send({ error: "bad_signature" });
    }
    if (event.type === "email.bounced") {
      await markEmailUndeliverable(event.data.to[0]);
    }
    return reply.status(204).send();
  });
}
