// src/auth/session.ts
export async function authedFetch(url: string, init: RequestInit = {}) {
  let res = await fetch(url, withBearer(init, await getAccess()));
  if (res.status === 401) {
    await refreshSession();
    res = await fetch(url, withBearer(init, await getAccess()));
  }
