There wasn't one. This is a flat Vitest test in given/when/then style, with no describe blocks:

```ts
import { mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { expect, test } from "vitest";
import { lockfileHash } from "../scripts/lockfile-hash";

const inDirWithLockfile = async (content: string) => {
  const dir = await mkdtemp(join(tmpdir(), "lockhash-"));
  await writeFile(join(dir, "pnpm-lock.yaml"), content);
  process.chdir(dir);
};

test("given a pnpm-lock.yaml, when hashing, then it returns a 16 char hex digest", async () => {
  await inDirWithLockfile("lockfileVersion: '9.0'\n");
  expect(await lockfileHash()).toMatch(/^[0-9a-f]{16}$/);
});

test("given two different lockfiles, when hashing, then the digests differ", async () => {
  await inDirWithLockfile("a: 1\n");
  const first = await lockfileHash();
  await inDirWithLockfile("a: 2\n");
  expect(await lockfileHash()).not.toBe(first);
});
```

